/* From Uiverse.io by Na3ar-17  - Tags: simple, material design, switch */
.__UIV_SCOPE__ .container {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: Arial, Helvetica, sans-serif;
  color: #fff;
}

.__UIV_SCOPE__ .switch {
  font-size: 0.875rem;
  position: relative;
  display: inline-block;
  width: 9em;
  height: 2.6em;
}

.__UIV_SCOPE__ .switch input {
  display: none;
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .switch input:checked + .slider .ball {
  box-shadow: 10px 10px 100px #7f8996;
}

.__UIV_SCOPE__ .switch input:checked + .slider .title {
  left: 40%;
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background-color: #8a5cd4;
}

.__UIV_SCOPE__ .switch input:focus + .slider {
  box-shadow: 10px 10px 100px #7f8996;
}

.__UIV_SCOPE__ .switch input:checked + .slider .ball {
  left: 72%;
  transform: rotate(360deg);
  box-shadow: none;
  outline: 6px solid rgba(255, 255, 255, 0.278);
}

.__UIV_SCOPE__ .switch .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #313033;
  transition: all 0.4s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .switch .slider .title {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-weight: 600;
  transition: all 0.4s;
  -webkit-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.__UIV_SCOPE__ .switch .slider .ball {
  background-color: #fff;
  height: 36px;
  width: 36px;
  border-radius: 50%;
  position: absolute;
  left: -1px;
  transition: 0.4s;
}

.__UIV_SCOPE__ .switch .slider .ball .icon {
  position: absolute;
  top: 58%;
  left: 53%;
  transform: translate(-50%, -50%);
  color: #313033;
  font-size: 12px;
}
